import{_ as d,o as e,c as o,ah as r}from"./chunks/framework.DjU4PSOm.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"tags":["computer/project"],"date":"2026-11-09T00:00:00.000Z"},"headers":[{"level":3,"title":"오늘 한 것 (2026-10-28 ~ 11-09)","slug":"오늘-한-것-2026-10-28-11-09","link":"#오늘-한-것-2026-10-28-11-09","children":[]},{"level":3,"title":"1. Android에서 처음 실행 — SDK 버전 문제","slug":"_1-android에서-처음-실행-—-sdk-버전-문제","link":"#_1-android에서-처음-실행-—-sdk-버전-문제","children":[]},{"level":3,"title":"2. 써보고 나온 의견들","slug":"_2-써보고-나온-의견들","link":"#_2-써보고-나온-의견들","children":[]},{"level":3,"title":"3. 규칙 조정","slug":"_3-규칙-조정","link":"#_3-규칙-조정","children":[]},{"level":3,"title":"4. 피드 — 한 장씩, 넘기면 끝","slug":"_4-피드-—-한-장씩-넘기면-끝","link":"#_4-피드-—-한-장씩-넘기면-끝","children":[]},{"level":3,"title":"5. Supabase MCP — 이제 SQL을 붙여넣지 않는다","slug":"_5-supabase-mcp-—-이제-sql을-붙여넣지-않는다","link":"#_5-supabase-mcp-—-이제-sql을-붙여넣지-않는다","children":[]},{"level":3,"title":"6. 기타 결정","slug":"_6-기타-결정","link":"#_6-기타-결정","children":[]},{"level":3,"title":"7. 남은 과제","slug":"_7-남은-과제","link":"#_7-남은-과제","children":[]}],"relativePath":"computer/project/Zing/11. 피드 개편과 규칙 조정, Android 실행 (2026-11-09).md","filePath":"computer/project/Zing/11. 피드 개편과 규칙 조정, Android 실행 (2026-11-09).md"}'),a={name:"computer/project/Zing/11. 피드 개편과 규칙 조정, Android 실행 (2026-11-09).md"};function l(i,t,n,s,c,u){return e(),o("div",null,[...t[0]||(t[0]=[r('<h3 id="오늘-한-것-2026-10-28-11-09" tabindex="-1">오늘 한 것 (2026-10-28 ~ 11-09) <a class="header-anchor" href="#오늘-한-것-2026-10-28-11-09" aria-label="Permalink to &quot;오늘 한 것 (2026-10-28 ~ 11-09)&quot;">​</a></h3><p>처음으로 <strong>Android 폰에서 앱을 띄웠고</strong>, 써보면서 나온 의견으로 피드와 규칙을 크게 바꿨다. 그리고 DB 작업을 AI가 직접 할 수 있게 Supabase를 연결했다.</p><table tabindex="0"><thead><tr><th>순서</th><th>작업</th><th>상태</th></tr></thead><tbody><tr><td>1</td><td>Expo SDK 57 → 58 업그레이드, Android Expo Go 실행</td><td>완료</td></tr><tr><td>2</td><td>&quot;내 일기&quot; 탭</td><td>완료</td></tr><tr><td>3</td><td>교환일기 화면에 상대 일기만 보이게</td><td>완료</td></tr><tr><td>4</td><td>규칙 조정: 징 하루 2회, 단계 기준 변경, 모르는 사람에게도 반응</td><td>완료</td></tr><tr><td>5</td><td>피드를 카드 한 장씩 넘기는 방식으로, 넘긴 일기는 다시 안 나옴</td><td>완료</td></tr><tr><td>6</td><td>Supabase MCP 연결 (AI가 SQL 직접 적용)</td><td>완료</td></tr><tr><td>7</td><td>검증 후 push</td><td>완료</td></tr></tbody></table><hr><h3 id="_1-android에서-처음-실행-—-sdk-버전-문제" tabindex="-1">1. Android에서 처음 실행 — SDK 버전 문제 <a class="header-anchor" href="#_1-android에서-처음-실행-—-sdk-버전-문제" aria-label="Permalink to &quot;1. Android에서 처음 실행 — SDK 버전 문제&quot;">​</a></h3><p>Expo Go로 폰에서 열었더니 &quot;Project is incompatible with this version of Expo Go&quot; 에러.</p><ul><li>원인: Play 스토어의 Expo Go는 <strong>항상 최신 SDK(58)만</strong> 지원하는데, 프로젝트는 57.</li><li>선택지: 옛날 Expo Go APK를 따로 설치 vs 프로젝트를 58로 올리기</li><li><strong>프로젝트를 올림.</strong> 팀원도 스토어에서 받으면 최신이라 같은 문제를 겪기 때문. <code>npx expo install expo@^58</code> → <code>npx expo install --fix</code>로 관련 라이브러리 버전 맞춤 → <code>expo-doctor</code> 20/20 통과.</li></ul><p>연결 원리: PC의 Metro 서버(8081)가 코드를 JS 번들로 묶어주고, 폰의 Expo Go가 같은 와이파이로 <code>exp://&lt;PC IP&gt;:8081</code>에서 받아 실행. 화면은 웹뷰가 아니라 진짜 Android UI로 그려짐. 데이터(Supabase)는 PC를 거치지 않고 폰이 직접 통신.</p><h3 id="_2-써보고-나온-의견들" tabindex="-1">2. 써보고 나온 의견들 <a class="header-anchor" href="#_2-써보고-나온-의견들" aria-label="Permalink to &quot;2. 써보고 나온 의견들&quot;">​</a></h3><table tabindex="0"><thead><tr><th>의견</th><th>반영</th></tr></thead><tbody><tr><td>내 일기를 볼 곳이 없음</td><td>&quot;내 일기&quot; 탭 추가 (일기별 받은 반응 개수도 표시)</td></tr><tr><td>교환일기에 내 일기까지 섞여서 헷갈림</td><td>상대 일기만 표시 (내 일기는 진행도 계산에만 사용)</td></tr><tr><td>다 목록으로 떠서 별로, 릴스처럼 하나씩</td><td>피드를 카드 한 장씩 넘기는 방식으로</td></tr><tr><td>1단계(반응만)가 너무 김</td><td>2단계는 매칭 다음날 0시에 바로 열림</td></tr><tr><td>모르는 사람한테도 반응하고 싶음</td><td>피드에서 아무 일기에나 반응 가능</td></tr></tbody></table><h3 id="_3-규칙-조정" tabindex="-1">3. 규칙 조정 <a class="header-anchor" href="#_3-규칙-조정" aria-label="Permalink to &quot;3. 규칙 조정&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>전</th><th>후</th></tr></thead><tbody><tr><td>하루 새 징</td><td>3회</td><td>2회</td></tr><tr><td>2단계</td><td>둘 다 일기 2개</td><td>매칭 다음날 0시(한국 시간)</td></tr><tr><td>3단계</td><td>둘 다 일기 4개</td><td>둘 다 일기 2개</td></tr><tr><td>4단계</td><td>둘 다 일기 7개</td><td>둘 다 일기 4개</td></tr><tr><td>반응</td><td>매칭 상대만</td><td>아무 일기 (내 것 제외)</td></tr></tbody></table><p>둘 다 매일 쓰면 매칭 다음날 2단계, 2일째 3단계, 4일째 4단계. 전에는 4단계까지 최소 7일이었다.</p><p>모르는 사람의 반응은 &quot;내 일기&quot; 탭에 <strong>개수만</strong> 보이고 누가 남겼는지는 안 보이게 했다 (<code>get_my_diary_reactions</code>가 사람 정보를 아예 안 돌려줌).</p><h3 id="_4-피드-—-한-장씩-넘기면-끝" tabindex="-1">4. 피드 — 한 장씩, 넘기면 끝 <a class="header-anchor" href="#_4-피드-—-한-장씩-넘기면-끝" aria-label="Permalink to &quot;4. 피드 — 한 장씩, 넘기면 끝&quot;">​</a></h3><p>처음엔 목록(FlatList)을 화면 높이로 끊어서 넘기는 방식으로 만들었는데, 써보니 요구가 더 분명해졌다: <strong>&quot;한 번 넘긴 건 다시 올려서 못 보게, 랜덤으로도 다시 안 나오게. 지금은 3개 뜨고 새로고침하는 식이잖아.&quot;</strong></p><p>그래서 구조를 바꿨다.</p><ul><li><strong>목록이 아니라 카드 한 장.</strong> <code>PanResponder</code> + <code>Animated</code>로 위로 밀면 카드가 날아가고 다음 카드가 올라옴. 아래로 밀면 살짝 끌리다 제자리로 (이전 카드가 애초에 없음).</li><li><strong>넘긴 일기 DB 기록</strong> (<code>diary_views</code> 테이블, <code>mark_diary_seen</code>). 화면에 &quot;보여준 것&quot;이 아니라 &quot;넘긴 것&quot;만 기록 — 보다가 앱을 닫으면 그 카드부터 다시 나옴.</li><li><strong>랜덤은 DB에서</strong> (<code>get_feed</code>, <code>order by random()</code>). 전에는 최신 100개를 받아 앱에서 섞었다. 이제 DB가 안 넘긴 일기만 골라서 10장씩 줌. 남은 카드가 3장 이하가 되면 미리 다음 10장 → 끊김 없음.</li><li><strong>이미 받아둔 카드는 다시 안 받게</strong> <code>exclude_ids</code>로 전달. 넘긴 직후 DB 기록이 끝나기 전에 다음 묶음을 요청하는 경우를 대비해 이번 세션에 넘긴 id도 같이 보냄.</li><li>덤으로 <strong>절반 공개 보안이 조금 나아짐</strong>: <code>get_feed</code>가 본문 앞 절반만 돌려줘서, 피드 응답에는 전문이 아예 없다. (단 <code>diaries</code> 테이블 직접 조회로는 아직 전문이 보임 — 남은 과제)</li></ul><p>검증 (테스트 계정 C, D):</p><ul><li>C가 D 일기에 ❤️ → D의 &quot;내 일기&quot;에 &quot;❤️ 1&quot;</li><li>터치로 위로 밀면 0.8초 안에 다음 카드, 넘긴 수만큼 <code>diary_views</code>에 기록</li><li>새로고침해도 넘긴 일기는 다시 안 나옴</li></ul><h3 id="_5-supabase-mcp-—-이제-sql을-붙여넣지-않는다" tabindex="-1">5. Supabase MCP — 이제 SQL을 붙여넣지 않는다 <a class="header-anchor" href="#_5-supabase-mcp-—-이제-sql을-붙여넣지-않는다" aria-label="Permalink to &quot;5. Supabase MCP — 이제 SQL을 붙여넣지 않는다&quot;">​</a></h3><p>지금까지는 AI가 SQL 파일을 쓰면 내가 대시보드 SQL Editor에 붙여넣어 실행했다. 이번에 <strong>Supabase 공식 MCP</strong>를 Claude Code에 연결해서 AI가 직접 적용하게 했다.</p><ul><li>방법 비교: CLI(<code>supabase link</code>)는 DB 비밀번호 입력이 필요하고 할 수 있는 게 마이그레이션 적용 정도. MCP는 브라우저에서 승인 한 번이면 되고 SQL 실행·테이블 조회·로그·보안 점검까지 가능 → MCP 선택.</li><li>범위는 Zing 프로젝트 하나로 제한 (<code>project_ref</code>를 주소에 고정).</li><li>첫 시도는 연결 타임아웃 — <strong>무료 플랜이 7일 넘게 안 쓰면 자동 일시정지</strong>돼 있었다. 대시보드에서 Restore.</li><li>두 번째 시도는 &quot;Migration was declined&quot; — 승인 없이 실행되게 설정했는데도 거절됨. 원인은 SQL 안의 <code>drop function</code> 줄. Supabase MCP가 <strong>삭제가 들어간 문장은 따로 확인을 요구</strong>하는데 그 확인 창을 띄울 수 없어 자동 거절된 것. 새로 만드는 함수라 <code>drop</code>이 필요 없어서 빼고 <code>create or replace</code>만으로 적용 → 성공.</li><li>적용 후 보안 점검(<code>get_advisors</code>)도 돌림. 대부분 의도한 설계(정책 없는 테이블, 로그인 유저가 부르는 <code>security definer</code> 함수). 확인 필요한 건 우리가 안 만든 <code>rls_auto_enable()</code> 함수를 비로그인 사용자도 호출 가능하다는 것 1건.</li></ul><h3 id="_6-기타-결정" tabindex="-1">6. 기타 결정 <a class="header-anchor" href="#_6-기타-결정" aria-label="Permalink to &quot;6. 기타 결정&quot;">​</a></h3><ul><li><strong>AWS로 옮길까?</strong> → 안 옮김. Supabase가 해주는 로그인·자동 API·권한 규칙을 AWS에서는 전부 직접 조립해야 하고, 사용자 적을 땐 오히려 비쌈. Supabase도 Postgres라 나중에 옮길 수 있고, 규칙을 DB 함수에 모아둬서 SQL은 대부분 재사용 가능.</li><li><strong>지인끼리 쓰는 앱으로?</strong> → 안 함. 지인용 교환일기 앱은 이미 있음(다이어링 등). Zing의 자리는 &quot;모르는 외국인과의 교환일기&quot;. 친구 초대는 초기 사용자 확보용 보조 기능으로 검토.</li></ul><h3 id="_7-남은-과제" tabindex="-1">7. 남은 과제 <a class="header-anchor" href="#_7-남은-과제" aria-label="Permalink to &quot;7. 남은 과제&quot;">​</a></h3><ul><li>2단계(앱이 주는 오늘의 질문, 5자 답변)부터 미구현</li><li><code>diaries</code> 테이블 직접 조회로 전문이 보이는 문제 (절반 공개 DB 보호)</li><li>일기 하루 1개 제한은 기기 시간 자정, 징·단계는 한국 시간 자정 — 기준 통일</li><li><code>rls_auto_enable()</code> 함수 확인</li><li>같은 사람 일기가 피드에 여러 장 나올 수 있음 (1인 1장으로 할지)</li><li>테스트 계정 일기가 적어서 폰에서 넘기는 느낌을 보기 어려움 → 테스트용 일기 더 필요</li><li>런칭 전: Supabase &quot;Confirm email&quot; 다시 켜기, <code>.ac.kr</code> 체크, Pro 플랜(자동 일시정지 방지)</li></ul>',27)])])}const h=d(a,[["render",l]]);export{p as __pageData,h as default};
